import json
import math
import statistics as st

c = {"AAA": [100.0, 101.0, 99.5, 102.0, 103.5, 102.8], "BBB": [50.0, 50.4, 50.9, 51.3, 51.6, 52.2]}
r = {t: [math.log(v[i] / v[i - 1]) for i in range(1, 6)] for t, v in c.items()}
vol = {
    t: [None if i < 2 else math.sqrt(252) * st.stdev(x[i - 2 : i]) for i in range(5)]
    for t, x in r.items()
}
print(json.dumps(r))
print(json.dumps(vol))
x = r["AAA"]
m = st.mean(x)
s = st.stdev(x)
print(252 * m, math.sqrt(252) * s, 252 * m / (math.sqrt(252) * s), vol["AAA"][-1])
print(99.5 / 101 - 1)
